import numpy as np

class Simulator:
    def __init__(self, controller=None):
        self.controller = controller

    def simulate(self, x0, ref, t):
        dt = t[1] - t[0]
        x = x0
        y_hist = []

        for _ in t:
            error = ref - x
            u = self.controller.compute(error, dt) if self.controller else 0
            x = x + dt * (-x + u)
            y_hist.append(x)

        return np.array(y_hist)

import pymupdf  # Atualizado de 'fitz' para 'pymupdf'
from pypdf import PdfReader, PdfWriter  # 'PdfMerger' substituído por 'PdfWriter'

class PDFEditor:

    @staticmethod
    def merge(pdf_list, output_path):
        """Une múltiplos arquivos PDF em um único documento usando PdfWriter."""
        writer = PdfWriter()
        try:
            for pdf in pdf_list:
                writer.append(pdf)

            with open(output_path, "wb") as f:
                writer.write(f)
            print(f"[sucesso] PDFs unidos com sucesso em: {output_path}")
        except Exception as e:
            print(f"[erro] Falha ao juntar os PDFs: {e}")
        finally:
            writer.close()
